  const navAlone = (t) => `<div class="pnav-navs">${sideNav({ groups: PNAV_HR_NAV, current: "휴가 현황", hover: "캘린더", logo: "Porest HR", height: 620 })}${sideNav({ groups: PNAV_DESK_NAV, current: "나무증권", collapsed: true, height: 620 })}</div>`;
